def ui_lookup(lang: str, key: str) -> str | None:
    """查 UI 补充词典;未命中返回 None(交由主词典/回退处理)。"""
    row = S.get(key)
    if not row:
        return None
    try:
        return row[LANGS.index(lang)]
    except (ValueError, IndexError):
        return row[0]
